class Manacher:
    PIPE = "|"

    def __init__(self, input_string) -> None:
        self.input_string = input_string

    def palindromic_length(self, center, diff, string):
        if (center - diff == -1 or center + diff == len(string)
                or string[center - diff] != string[center + diff]):
            return 0
        return 1 + self.palindromic_length(center, diff + 1, string)

    def build_transformed_string(self):
        new_input_string = ""
        for i in self.input_string[:len(self.input_string) - 1]:
            new_input_string += i + self.PIPE
        new_input_string += self.input_string[-1]
        return new_input_string

    def find_max_palindrome_length(self, new_input_string):
        max_length = 0
        start = 0
        for i in range(len(new_input_string)):
            length = self.palindromic_length(i, 1, new_input_string)
            if max_length < length:
                max_length = length
                start = i
        return max_length, start

    def extract_original_palindrome(self, new_input_string, start, max_length):
        output_string = ""
        for i in new_input_string[start - max_length:start + max_length + 1]:
            if i != self.PIPE:
                output_string += i
        return output_string

    def palindromic_string(self):
        new_input_string = self.build_transformed_string()
        max_length, start = self.find_max_palindrome_length(new_input_string)
        output_string = self.extract_original_palindrome(new_input_string, start, max_length)
        return output_string
